<script setup lang="ts">
import {ref,computed} from 'vue';import {useWorkbench} from '../stores/workbench';import {api} from '../api/client';import UiIcon from './UiIcon.vue';const s=useWorkbench(),showDiff=ref(false),showLogs=ref(false),a=ref(1),b=ref(1),diff=ref<any>(null);const versions=computed(()=>s.versions);async function openDiff(v?:number){if(!versions.value.length)return;a.value=versions.value[0].version;b.value=v||versions.value[versions.value.length-1].version;showDiff.value=true;await compare();}async function compare(){try{diff.value=await api('/tasks/'+s.taskId+'/diff?a='+a.value+'&b='+b.value)}catch(e:any){s.error=e.message}}async function logs(){await s.loadLogs();showLogs.value=true;}const display=(x:any)=>x===null||x===undefined?'—':typeof x==='object'?JSON.stringify(x):String(x);
</script><template><div class="version-footer"><div class="icon-label"><UiIcon name="clock"/><strong>规格版本</strong><span v-if="!versions.length" class="muted">确认规格后保存首个版本</span><div v-else class="version-chain"><template v-for="(v,i) in versions" :key="v.version"><span v-if="i" class="version-arrow">→</span><button :class="{active:v.version===s.spec?.version}" @click="openDiff(v.version)" :title="v.change_reason||'确认规格'">v{{v.version}}<small>{{v.status==='draft'?'草稿':''}}</small></button></template></div></div><div class="actions"><el-button v-if="versions.length>1" text @click="openDiff()">版本差异</el-button><el-button :disabled="!s.taskId" text @click="logs">运行日志 <UiIcon name="chevron" :size="14"/></el-button></div></div><el-dialog v-model="showDiff" title="规格版本差异" width="850px"><div class="actions"><el-select v-model="a" class="compact-select"><el-option v-for="v in versions" :key="v.version" :label="'v'+v.version" :value="v.version"/></el-select><span>→</span><el-select v-model="b" class="compact-select"><el-option v-for="v in versions" :key="v.version" :label="'v'+v.version" :value="v.version"/></el-select><el-button @click="compare">对比</el-button></div><el-table :data="diff?.changes||[]" stripe><el-table-column prop="path" label="字段" width="220"/><el-table-column prop="kind" label="类型" width="90"/><el-table-column label="原版本"><template #default="{row}"><code>{{display(row.before)}}</code></template></el-table-column><el-table-column label="新版本"><template #default="{row}"><code>{{display(row.after)}}</code></template></el-table-column></el-table><el-empty v-if="diff&&!diff.changes?.length" description="两个版本没有规格差异。"/></el-dialog><el-drawer v-model="showLogs" title="任务运行日志" size="650px"><p class="small-note">{{s.taskId}}</p><div v-for="(l,i) in s.logs" :key="i" class="task-log"><time>{{l.time}}</time><span>{{l.message||l}}</span></div><el-empty v-if="!s.logs.length" description="当前任务尚无日志。"/></el-drawer></template>